CREATE DATABASE IF NOT EXISTS wovenheritage
    CHARACTER SET utf8mb4
    COLLATE utf8mb4_unicode_ci;

USE wovenheritage;
CREATE TABLE IF NOT EXISTS `users` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `email` varchar(150) NOT NULL,
  `password` varchar(255) NOT NULL,
  `phone` varchar(20) DEFAULT NULL,
  `address` text DEFAULT NULL,
  `role` enum('client','admin') DEFAULT 'client',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `categories` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `slug` varchar(100) NOT NULL,
  `description` text DEFAULT NULL,
  `image` varchar(255) DEFAULT NULL,
  `sort_order` int(11) DEFAULT 0,
  `parent_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `products` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(200) NOT NULL,
  `description` text DEFAULT NULL,
  `price` decimal(10,2) NOT NULL,
  `old_price` decimal(10,2) DEFAULT NULL,
  `stock` int(11) DEFAULT 10,
  `category_id` int(11) DEFAULT NULL,
  `image` varchar(255) DEFAULT NULL,
  `badge` enum('new','sale','best','') DEFAULT '',
  `is_featured` tinyint(1) DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `category_id` (`category_id`),
  CONSTRAINT `products_ibfk_1` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `orders` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) DEFAULT NULL,
  `guest_name` varchar(100) DEFAULT NULL,
  `guest_email` varchar(150) DEFAULT NULL,
  `guest_phone` varchar(20) DEFAULT NULL,
  `shipping_address` text DEFAULT NULL,
  `total` decimal(10,2) NOT NULL,
  `status` enum('pending','confirmed','shipped','delivered','cancelled') DEFAULT 'pending',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `orders_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `order_items` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL,
  `product_id` int(11) DEFAULT NULL,
  `product_name` varchar(200) DEFAULT NULL,
  `quantity` int(11) NOT NULL,
  `price` decimal(10,2) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `order_id` (`order_id`),
  KEY `product_id` (`product_id`),
  CONSTRAINT `order_items_ibfk_1` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE,
  CONSTRAINT `order_items_ibfk_2` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


INSERT INTO `categories` (`id`, `name`, `slug`, `description`, `image`, `sort_order`, `parent_id`) VALUES (1,'Vêtements Femmes','femmes','Toute notre collection de melhfas sahraouies : gaze, chega, persi, digital et plus.','womens-clothes/Melhfa-Chega-033-A-350x434.jpg',1,NULL),(2,'Vêtements Hommes','hommes','Tenues sahraouies traditionnelles pour hommes : daraas, turbans et pantalons amples.','mens-clothes/melhfa-tenue-sahraouia-blanc-dore (2).jpg',2,NULL),(3,'Accessoires','accessoires','Accessoires sahraouiens artisanaux : bijoux, ceintures brodées et ornements traditionnels.','saharawian-accessories/il_794xN.6566079668_te8c.png',3,NULL),(5,'Melhfa Gaze','melhfa-gaze','Melhfas en tissu gaze léger et transparent, parfaites pour les journées chaudes.','womens-clothes/Melhfa-Gaze-036-A-350x434.webp',10,1),(6,'Melhfa Chega','melhfa-chega','Melhfas en tissu chega épais et de haute qualité, pour les grandes occasions.','womens-clothes/Melhfa-Chega-036-A-350x434.webp',11,1),(7,'Melhfa Digital','melhfa-digital','Melhfas à imprimé numérique, motifs modernes alliant tradition et modernité.','womens-clothes/Melhfa-Digital-062-B-350x434.jpg',12,1),(8,'Melhfa Persi','melhfa-persi','Melhfas en tissu Persi d\'inspiration orientale, designs raffinés aux motifs persans.','womens-clothes/Melhfa-Persi-116-A-350x434.webp',13,1),(9,'Melhfa Diana London','melhfa-diana-london','Melhfas en tissu de marque Diana London, qualité britannique et finitions impeccables.','womens-clothes/Melhfa-Diana-London-116-A-350x434.webp',14,1),(10,'Melhfa Second Life','melhfa-second-life','Melhfas en tissu Second Life recyclé et durable, mode éco-responsable sans compromis.','womens-clothes/Melhfa-Second-Life-116-A-350x434.webp',15,1),(11,'Melhfa Uni','melhfa-uni','Melhfas en tissu uni de couleur unie, élégance simple et intemporelle.','womens-clothes/Melhfa-Uni-036-A-350x434.webp',16,1),(12,'Melhfa Kanebo','melhfa-kanebo','Melhfas en tissu Kanebo de haute gamme, douceur exceptionnelle et tombé parfait.','womens-clothes/Melhfa-Kanebo-124-A-350x434.jpg',17,1),(13,'Melhfa Kento Italy','melhfa-kento-italy','Melhfas en tissu Kento Italy de fabrication italienne, le summum du luxe artisanal.','womens-clothes/Melhfa-Kento-Italy-116-A-350x434.webp',18,1),(24,'Turbans','turbans','Turbans et chèches sahraouiens traditionnels, protection et style du désert.','mens-clothes/il_794xN.3536580251_ersx.webp',21,2),(25,'Pantalons','pantalons','Pantalons sahraouiens amples et confortables, coupe traditionnelle en tissu léger.','mens-clothes/il_794xN.3621779360_nc43.webp',22,2),(26,'Daraas','daraas','Daraas sahraouies traditionnelles pour hommes, tenues complètes brodées main.','mens-clothes/melhfa-tenue-sahraouia-blanc-dore (2).jpg',1,2);
;


